262		t, err := ss.s.TicketBySlug(slug)
263		if store.IsNotFound(err) {
264			return nil, fmt.Errorf("%w: %q", notFoundErr, slug)
265		}
266		if err != nil {
267			return nil, err
268		}
269		return t, nil
270	}
